const eintraege = $input.all();
const heute = new Date().toISOString().slice(0, 10);

// Finde den Eintrag für heute
const heuteEintrag = eintraege.find(e => e.json.datum === heute && e.json.status !== 'gepostet');

if (heuteEintrag) {
  return [heuteEintrag];
}

// Kein geplanter Content — generiere Thema basierend auf Wochentag
const wochentag = new Date().getDay();
const themen = {
  1: { typ: 'tipp', thema: 'Praxis-Tipp zur Buchhaltungsautomatisierung', plattformen: ['linkedin', 'instagram'] },
  3: { typ: 'case_study', thema: 'Fallstudie: Wie KI die Belegverarbeitung verändert', plattformen: ['linkedin', 'youtube'] },
  5: { typ: 'behind_scenes', thema: 'Behind-the-Scenes: So arbeitet unser KI-Agent', plattformen: ['instagram', 'tiktok', 'x'] }
};

const t = themen[wochentag] || themen[1];
return [{ json: { ...t, datum: heute, status: 'auto_generiert' } }];

const content = $input.first().json;
const plattformen = $('Thema bestimmen').first().json.plattformen || [];
const results = [];

for (const p of plattformen) {
  if (content[p]) {
    results.push({ json: { plattform: p, content: content[p], datum: new Date().toISOString().slice(0, 10) } });
  }
}

return results;
